# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

untrustedImageRepo contains msga if {
	wl := input[_]
	containers_path := get_containers_path(wl)
	containers := object.get(wl, containers_path, [])
	container := containers[i]
	name := image.parse_normalized_name(container.image)
	not image_in_allowed_list(name)
	path := sprintf("%s[%d].image", [concat(".", containers_path), i])

	msga := {
		"alertMessage": sprintf("image '%v' in container '%s' comes from untrusted registry", [name, container.name]),
		"packagename": "armo_builtins",
		"alertScore": 2,
		"fixPaths": [],
		"reviewPaths": [path],
		"failedPaths": [path],
		"alertObject": {"k8sApiObjects": [wl]},
	}
}

# image_in_allowed_list - rule to check if an image complies with imageRepositoryAllowList.
image_in_allowed_list(image) if {
	# see default-config-inputs.json for list values
	allowedlist := data.postureControlInputs.imageRepositoryAllowList
	registry := allowedlist[_]
	startswith(image, registry)
}

# get_containers_path - get resource containers paths for  {"Deployment","ReplicaSet","DaemonSet","StatefulSet","Job"}
get_containers_path(resource) := result if {
	resource_kinds := {"Deployment", "ReplicaSet", "DaemonSet", "StatefulSet", "Job"}
	resource_kinds[resource.kind]
	result = ["spec", "template", "spec", "containers"]
}

# get_containers_path - get resource containers paths for "Pod"
get_containers_path(resource) := result if {
	resource.kind == "Pod"
	result = ["spec", "containers"]
}

# get_containers_path - get resource containers paths for  "CronJob"
get_containers_path(resource) := result if {
	resource.kind == "CronJob"
	result = ["spec", "jobTemplate", "spec", "template", "spec", "containers"]
}

# regal ignore:directory-package-mismatch 
package armo_builtins

import rego.v1

# CIS 2.7 https://workbench.cisecurity.org/sections/1126654/recommendations/1838578

deny contains msga if {
	etcdPod := [pod | pod := input[_]; filter_input(pod, "etcd")]
	etcdCheckResult := get_argument_value_with_path(etcdPod[0].spec.containers[0], "--trusted-ca-file")

	apiserverPod := [pod | pod := input[_]; filter_input(pod, "kube-apiserver")]
	apiserverCheckResult := get_argument_value_with_path(apiserverPod[0].spec.containers[0], "--client-ca-file")

	etcdCheckResult.value == apiserverCheckResult.value
	msga := {
		"alertMessage": "Cert file is the same both for the api server and the etcd",
		"alertScore": 8,
		"packagename": "armo_builtins",
		"reviewPaths": [etcdCheckResult.path, apiserverCheckResult.path],
		"failedPaths": [etcdCheckResult.path, apiserverCheckResult.path],
		"fixPaths": [etcdCheckResult.fix_paths, apiserverCheckResult.fix_paths],
		"alertObject": {"k8sApiObjects": [etcdPod[0], apiserverPod[0]]},
	}
}

command_api_server_or_etcd(cmd) if {
	endswith(cmd, "kube-apiserver")
}

command_api_server_or_etcd(cmd) if {
	endswith(cmd, "etcd")
}

filter_input(obj, res) if {
	obj.apiVersion == "v1"
	obj.kind == "Pod"
	count(obj.spec.containers) == 1
	endswith(split(obj.spec.containers[0].command[0], " ")[0], res)
}

get_argument_value(command, argument) := value if {
	args := split(command, "=")
	some i, val in args
	val == sprintf("%v", [argument])
	value := args[i + 1]
}

get_argument_value_with_path(container, argument) := result if {
	cmd := get_flags(container)
	contains(cmd[i], argument)
	argumentValue := get_argument_value(cmd[i], argument)
	path := flag_path(container, i)
	result = {
		"path": path,
		"value": argumentValue,
		"fix_paths": {"path": path, "value": "<path/to/different-tls-certificate-file.crt>"},
	}
}

# Combine command and args so flags are detected regardless of where the
# distribution places them. kubeadm puts flags in command; RKE2/k3s keep
# command as ["<binary>"] and pass all flags via args.
get_flags(container) := array.concat(container.command, [arg | arg := container.args[_]])

# Map an index into the combined command+args list back to the real path, so
# findings on RKE2/k3s point at args[j] instead of a non-existent command[i].
flag_path(container, i) := sprintf("spec.containers[0].command[%d]", [i]) if {
	i < count(container.command)
} else := sprintf("spec.containers[0].args[%d]", [i - count(container.command)])

