	count(matchs) == 1
	values := [val | val := split(matchs[0][1], ",")[j]; val != ""]
	origin := matchs[0][0]
}

# Assume flag set only once
invalid_flag(container) := result if {
	cmd := get_flags(container)
	flag := get_flag_values(cmd[i])

	# value check
	not "EventRateLimit" in flag.values

	# get fixed and failed paths
	fixed_values := array.concat(flag.values, ["EventRateLimit"])
	fixed_flag = sprintf("%s=%s", ["--enable-admission-plugins", concat(",", fixed_values)])
	fixed_cmd = replace(cmd[i], flag.origin, fixed_flag)
	path := flag_path(container, i)

	result := {
		"failed_paths": [path],
		"fix_paths": [{
			"path": path,
			"value": fixed_cmd,
		}],
	}
}

invalid_flag(container) := result if {
	cmd := get_flags(container)
	full_cmd := concat(" ", cmd)
	not contains(full_cmd, "--enable-admission-plugins")

	path = append_path(container, 0)
	result = {
		"failed_paths": [],
		"fix_paths": [{
