ccnp_spec_default_deny_disabled(spec) if {
	spec.enableDefaultDeny.ingress == false
	spec.enableDefaultDeny.egress == false
}

ccnp_spec_has_ingress_or_egress(spec) if {
	spec.ingress
}

ccnp_spec_has_ingress_or_egress(spec) if {
	spec.egress
}

list_contains(list, element) if {
	some i
	list[i] == element
