# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

# Check if image scanning enabled for EKS
deny contains msga if {
	describe_repositories := input[_]
	describe_repositories.apiVersion == "eks.amazonaws.com/v1"
	describe_repositories.kind == "DescribeRepositories"
	describe_repositories.metadata.provider == "eks"
	repos := describe_repositories.data.Repositories
	some repo in repos
	not image_scanning_configured(repo)

	msga := {
		"alertMessage": "image scanning is not enabled",
		"alertScore": 3,
		"packagename": "armo_builtins",
		"failedPaths": [],
		"fixPaths": [],
		"fixCommand": "aws ecr put-image-scanning-configuration --repository-name $REPO_NAME --image-scanning-configuration scanOnPush=true --region $REGION_CODE",
		"alertObject": {
			"k8sApiObjects": [],
			"externalObjects": describe_repositories,
		},
	}
}

# NEW GCP GAR check
deny contains msga if {
	describe_repositories := input[_]
	describe_repositories.apiVersion == "container.googleapis.com/v1"
	describe_repositories.kind == "DescribeRepositories"
	describe_repositories.metadata.provider == "gke"

	repos := describe_repositories.data.registries
	some repo in repos
	not image_scanning_configured_gcp(repo)

	msga := {
		"alertMessage": "image scanning is not enabled for GCP Artifact Registry",
		"alertScore": 3,
		"packagename": "armo_builtins",
		"failedPaths": [],
		"fixPaths": [],
		"fixCommand": "gcloud artifacts repositories update $REPO_NAME --location=$LOCATION --allow-vulnerability-scanning",
		"alertObject": {
			"k8sApiObjects": [],
			"externalObjects": describe_repositories,
		},
	}
}

image_scanning_configured(repo) if {
	repo.ImageScanningConfiguration.ScanOnPush == true
}

image_scanning_configured_gcp(repo) if {
	repo.vulnerabilityScanningConfig.enableVulnerabilityScanning == true
}

# regal ignore:directory-package-mismatch
package armo_builtins

import rego.v1

# Encryption config is not using a recommended provider for KMS
deny contains msg if {
	some obj in input
	is_control_plane_info(obj)
	config_file := obj.data.APIServerInfo.encryptionProviderConfigFile
	config_file_content = decode_config_file(base64.decode(config_file.content))

	resources := config_file_content.resources
	every resource in resources {
		not has_recommended_provider(resource)
	}

	fix_paths := [
		{"path": sprintf("resources[%d].resources[%d]", [count(resources), 0]), "value": "secrets"},
		{"path": sprintf("resources[%d].providers[%d].kms", [count(resources), 0]), "value": "YOUR_EXTERNAL_KMS"},
	]

	# Add name and the originating host-sensor object's identity to the failed
	# object, so the backend can resolve it to a resource (same envelope shape
	# used by other host-sensor/externalObjects rules), and so it fits the
	# format of the alert object
	failed_obj := json.patch(config_file_content, [
		{"op": "add", "path": "name", "value": "encryption-provider-config"},
		{"op": "add", "path": "apiVersion", "value": obj.apiVersion},
		{"op": "add", "path": "kind", "value": obj.kind},
		{"op": "add", "path": "metadata", "value": obj.metadata},
	])

	msg := {
		"alertMessage": "Encryption provider config is not using a recommended provider for KMS",
		"alertScore": 2,
		"failedPaths": [],
		"fixPaths": fix_paths,
		"packagename": "armo_builtins",
		"alertObject": {"externalObjects": failed_obj},
	}
}

is_control_plane_info(obj) if {
	obj.apiVersion == "hostdata.kubescape.cloud/v1beta0"
	obj.kind == "ControlPlaneInfo"
}

decode_config_file(content) := parsed if {
	parsed := yaml.unmarshal(content)
} else := json.unmarshal(content)

has_recommended_provider(resource) if {
	recommended_providers := {"akeyless", "azurekmsprovider", "aws-encryption-provider"}
	some provider in resource.providers
	recommended_providers[provider.kms.name]
}

